<?php

namespace App\Services\Assistant;

use App\Models\User;
use App\Services\Reports\Capacity;
use App\Services\Reports\ReportFilters;
use Carbon\CarbonImmutable;

/**
 * A group of preset questions for one audience. Every answer is computed from the database at the time
 * it is asked and returned as typed blocks the UI renders (stats, list, progress, table, text). Nothing is
 * generated by a language model, so answers are exact and always scoped to the signed-in user.
 */
abstract class AnswerSet
{
    /** @return list<array{key: string, label: string, description: string, category: string, params?: list<array<string, mixed>>}> */
    abstract public function questions(User $user): array;

    /**
     * @param  array<string, mixed>  $params  already validated against the question's params
     * @return array{title: string, blocks: list<array<string, mixed>>, empty_message?: string|null}|null null when the key is not in this set
     */
    abstract public function answer(string $key, User $user, array $params): ?array;

    protected function today(): CarbonImmutable
    {
        return CarbonImmutable::now(config('app.timezone'))->startOfDay();
    }

    /** @return array{0: CarbonImmutable, 1: CarbonImmutable} Monday .. Sunday of the current ISO week */
    protected function week(): array
    {
        $monday = $this->today()->startOfWeek();

        return [$monday, $monday->addDays(6)];
    }

    /** @param array<string, mixed> $extra */
    protected function filters(CarbonImmutable $from, CarbonImmutable $to, array $extra = []): ReportFilters
    {
        return ReportFilters::fromArray(['from' => $from->toDateString(), 'to' => $to->toDateString(), 'per_page' => 100, ...$extra]);
    }

    protected function weekLabel(): string
    {
        [$from, $to] = $this->week();

        return $from->format('j M').' to '.$to->format('j M');
    }

    /** @param list<array{label: string, value: mixed, hint?: string|null, tone?: string|null}> $items */
    protected function stats(string $title, array $items): array
    {
        return ['type' => 'stats', 'title' => $title, 'items' => $items];
    }

    /** @param list<array{title: string, subtitle?: string|null, meta?: string|null, href?: string|null, tone?: string|null}> $items */
    protected function listBlock(string $title, array $items, ?string $empty = null): array
    {
        return ['type' => 'list', 'title' => $title, 'items' => $items, 'empty' => $empty];
    }

    /** Scheduled hours against capacity; `percent` and `band` use the same thresholds as the reports. */
    protected function progressItem(string $label, float $used, float $capacity, ?string $href = null): array
    {
        $percent = Capacity::utilization($used, $capacity);

        return [
            'label' => $label,
            'used' => round($used, 2),
            'capacity' => round($capacity, 2),
            'percent' => $percent,
            'band' => Capacity::band($percent),
            'href' => $href,
        ];
    }

    /** @param list<array<string, mixed>> $items */
    protected function progress(string $title, array $items, ?string $empty = null): array
    {
        return ['type' => 'progress', 'title' => $title, 'items' => $items, 'empty' => $empty];
    }

    /**
     * @param  list<string>  $columns
     * @param  list<list<mixed>>  $rows
     */
    protected function table(string $title, array $columns, array $rows, ?string $empty = null): array
    {
        return ['type' => 'table', 'title' => $title, 'columns' => $columns, 'rows' => $rows, 'empty' => $empty];
    }

    protected function text(string $text, string $tone = 'info'): array
    {
        return ['type' => 'text', 'text' => $text, 'tone' => $tone];
    }

    protected function hours(float $value): string
    {
        return rtrim(rtrim(number_format($value, 1, '.', ''), '0'), '.').' h';
    }

    protected function percent(?float $value): string
    {
        return $value === null ? '—' : rtrim(rtrim(number_format($value, 1, '.', ''), '0'), '.').'%';
    }

    protected function daysLate(string $due): int
    {
        return (int) CarbonImmutable::parse($due, config('app.timezone'))->startOfDay()->diffInDays($this->today());
    }

    protected function date(?string $value): ?string
    {
        return $value ? CarbonImmutable::parse($value, config('app.timezone'))->format('j M Y') : null;
    }
}
